"use client"

/**
 * Island Nav (Notchset) v1.0.0 · Notchset
 * Docs: https://notchset.dev/components/island-nav
 * MIT licensed: free to use, change and share.
 */

import * as React from "react"

import { cn } from "@/lib/utils"
import { inertRef, useIsomorphicLayoutEffect } from "@/lib/notchset/shared"
import { useSound } from "@/lib/notchset/sound"


const clock = () => performance.now()
/*
 * Island Nav: a floating nav that becomes its own menu. One pill glides behind the item under the
 * pointer (measured, never hard-coded); a click opens that item's menu and the island grows to fit it.
 * Moving to another menu waits for intent (140ms, and 320ms after the last switch), then slides the
 * content the way you travelled while the island resizes. Leaving the island or pressing Esc closes it.
 */

interface IslandNavItem {
  label: string
  /** A link item. */
  href?: string | undefined
  /** A menu item: its panel, and the island's width while it's open. */
  menu?: React.ReactNode | undefined
  width?: number | undefined
}

interface IslandNavProps extends Omit<React.ComponentPropsWithoutRef<"nav">, "children"> {
  brand: React.ReactNode
  items: readonly IslandNavItem[]
  /** The call to action at the end. */
  action?: React.ReactNode | undefined
  /** The island's width while closed. */
  width?: number | undefined
  sound?: boolean | undefined
}

const IslandNav = React.forwardRef<HTMLElement, IslandNavProps>(function IslandNav({ brand, items, action, width = 470, sound = true, className, onPointerLeave, onKeyDown, ...props }, ref) {
  const { sfx } = useSound(sound)
  const panelId = React.useId()
  const triggers = React.useRef<(HTMLElement | null)[]>([])
  const panel = React.useRef<HTMLDivElement>(null)
  const [hot, setHot] = React.useState(-1)
  const [pill, setPill] = React.useState<{ x: number; w: number } | null>(null)
  const [open, setOpen] = React.useState<{ i: number; dir: 1 | -1; key: number } | null>(null)
  const intent = React.useRef(0)
  const last = React.useRef(0)
  const focusPanel = React.useRef(false)

  useIsomorphicLayoutEffect(() => {
    const el = hot >= 0 ? triggers.current[hot] : null
    if (el) setPill({ x: el.offsetLeft, w: el.offsetWidth })
  }, [hot])
  React.useEffect(() => () => window.clearTimeout(intent.current), [])
  React.useEffect(() => {
    if (!open || !focusPanel.current) return
    focusPanel.current = false
    panel.current?.querySelector<HTMLElement>("a,button,[tabindex]")?.focus({ preventScroll: true })
  }, [open])

  const show = (i: number, toggle: boolean) => {
    last.current = clock()
    if (open?.i === i) {
      if (toggle) {
        sfx.swooshOut()
        setOpen(null)
      }
      return
    }
    if (!open) sfx.swooshIn()
    else sfx.turn(i > open.i ? 1 : -1)
    setOpen((o) => ({ i, dir: o && i < o.i ? -1 : 1, key: o ? o.key + 1 : 0 }))
  }
  const close = (refocus: boolean) => {
    window.clearTimeout(intent.current)
    if (!open) return
    sfx.swooshOut()
    if (refocus) triggers.current[open.i]?.focus()
    setOpen(null)
  }
  const enter = (i: number) => {
    if (hot !== i) sfx.tone(1200 + i * 120, 0.012, "triangle", 0.018)
    setHot(i)
    window.clearTimeout(intent.current)
    if (!open || open.i === i || !items[i]?.menu) return
    // Hover intent: switching on a pass-through restarts the panel's motion and leaves it faded.
    intent.current = window.setTimeout(() => show(i, false), Math.max(140, 320 - (clock() - last.current)))
  }

  const current = open ? items[open.i] : undefined

  return (
    <nav
      ref={ref}
      data-slot="island-nav"
      data-notchset=""
      data-state={open ? "open" : "closed"}
      onPointerLeave={(event) => {
        setHot(-1)
        close(false)
        onPointerLeave?.(event)
      }}
      onKeyDown={(event) => {
        if (event.key === "Escape" && open) {
          event.preventDefault()
          close(true)
        }
        onKeyDown?.(event)
      }}
      className={cn(
        "mx-auto max-w-[calc(100%-24px)] overflow-hidden border border-[var(--border)] bg-[var(--background)] text-[var(--foreground)] shadow-[var(--ns-shadow-layer)] [transition:width_.55s_cubic-bezier(.2,1.1,.3,1),border-radius_.5s_var(--ns-ease-settle)] motion-reduce:transition-none",
        open ? "rounded-[22px]" : "rounded-[28px]",
        className
      )}
      style={{ width: current?.width ?? width }}
      {...props}
    >
      <div className="relative flex h-[54px] items-center gap-0.5 ps-2 pe-1.5">
        <span className="me-2 flex shrink-0 items-center gap-2 text-[length:var(--ns-type-copy)] font-semibold tracking-[-0.02em]">{brand}</span>
        <div className="relative flex min-w-0 items-center">
          {pill && (
            <span
              aria-hidden="true"
              className={cn("absolute top-0 h-8 rounded-full bg-[var(--accent)] [transition:left_.4s_cubic-bezier(.2,1.25,.3,1),width_.4s_cubic-bezier(.2,1.25,.3,1),opacity_.2s]", hot >= 0 ? "opacity-100" : "opacity-0")}
              style={{ left: pill.x, width: pill.w }}
            />
          )}
          {items.map((item, i) =>
            item.menu ? (
              <button
                key={item.label}
                ref={(el) => {
                  triggers.current[i] = el
                }}
                type="button"
                aria-expanded={open?.i === i}
                aria-controls={panelId}
                onPointerEnter={() => enter(i)}
                onFocus={() => setHot(i)}
                onClick={(event) => {
                  window.clearTimeout(intent.current)
                  focusPanel.current = event.detail === 0
                  show(i, true)
                }}
                className="relative inline-flex h-[var(--ns-control-compact)] cursor-pointer items-center justify-center gap-1.5 rounded-[var(--radius)] px-2.5 text-[length:var(--ns-type-label)] font-medium whitespace-nowrap text-[var(--foreground)] outline-none focus-visible:ring-[length:var(--ns-focus-width,2px)] focus-visible:ring-[color:var(--ns-focus-color,var(--ring))]"
              >
                {item.label}
                <svg viewBox="0 0 24 24" aria-hidden="true" className={cn("size-3.5 [transition:rotate_.4s_var(--ns-ease-pop)]", open?.i === i && "rotate-180")} fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="m6 9 6 6 6-6" />
                </svg>
              </button>
            ) : (
              <a
                key={item.label}
                ref={(el) => {
                  triggers.current[i] = el
                }}
                href={item.href}
                onPointerEnter={() => enter(i)}
                onFocus={() => setHot(i)}
                className="relative inline-flex h-8 cursor-pointer items-center justify-center gap-1.5 rounded-[var(--radius)] px-2.5 text-[length:var(--ns-type-label)] font-medium whitespace-nowrap text-[var(--foreground)] outline-none focus-visible:ring-[length:var(--ns-focus-width,2px)] focus-visible:ring-[color:var(--ns-focus-color,var(--ring))]"
              >
                {item.label}
              </a>
            )
          )}
        </div>
        <span className="flex-1" />
        {action}
      </div>
      <div id={panelId} className={cn("grid [transition:grid-template-rows_.55s_var(--ns-ease-settle)] motion-reduce:transition-none", open ? "grid-rows-[1fr]" : "grid-rows-[0fr]")}>
        <div ref={inertRef(!open)} className="min-h-0 overflow-hidden">
          <div ref={panel} className={cn("relative px-2 pt-1 pb-2 [transition:opacity_.25s]", open ? "opacity-100" : "opacity-0")}>
            {open && current?.menu && (
              <div
                key={open.key}
                className={cn(
                  "motion-reduce:animate-none",
                  open.key === 0 && "animate-[ns-fade-up_.35s_.08s_both]",
                  open.key > 0 && open.dir > 0 && "animate-[ns-slide-l_.4s_var(--ns-ease-settle)_both] rtl:animate-[ns-slide-r_.4s_var(--ns-ease-settle)_both]",
                  open.key > 0 && open.dir < 0 && "animate-[ns-slide-r_.4s_var(--ns-ease-settle)_both] rtl:animate-[ns-slide-l_.4s_var(--ns-ease-settle)_both]"
                )}
              >
                {current.menu}
              </div>
            )}
          </div>
        </div>
      </div>
    </nav>
  )
})

interface IslandNavGridProps extends Omit<React.ComponentPropsWithoutRef<"div">, "children"> {
  items: readonly { title: string; description?: string | undefined; icon?: React.ReactNode | undefined; href: string }[]
  /** Beside the grid: a featured card. */
  aside?: React.ReactNode | undefined
  sound?: boolean | undefined
}

/** A menu panel: a two-column grid of links with one highlight that glides between them. */
function IslandNavGrid({ items, aside, sound = true, className, ...props }: IslandNavGridProps) {
  const { sfx } = useSound(sound)
  const [hot, setHot] = React.useState(-1)
  const go = (i: number) => {
    if (hot === i) return
    sfx.tone(1100 + i * 90, 0.015, "triangle", 0.02)
    setHot(i)
  }
  return (
    <div data-slot="island-nav-grid" className={cn("grid gap-2", aside ? "grid-cols-[minmax(0,1fr)_170px] max-sm:grid-cols-[minmax(0,1fr)]" : "grid-cols-[minmax(0,1fr)]", className)} {...props}>
      <div className="relative grid auto-rows-[58px] grid-cols-2 max-[480px]:grid-cols-1" onPointerLeave={() => setHot(-1)}>
        <span
          aria-hidden="true"
          className={cn("absolute start-0 top-0 h-[58px] w-1/2 rounded-[12px] bg-[var(--accent)] [--sx:1] [transition:translate_.4s_cubic-bezier(.2,1.25,.3,1),opacity_.2s] max-[480px]:hidden rtl:[--sx:-1]", hot >= 0 ? "opacity-100" : "opacity-0")}
          style={{ translate: `calc(${(Math.max(0, hot) % 2) * 100}% * var(--sx)) ${Math.floor(Math.max(0, hot) / 2) * 58}px` }}
        />
        {items.map((it, i) => (
          <a key={it.title} href={it.href} onPointerEnter={() => go(i)} onFocus={() => go(i)} className="relative flex items-center gap-2.5 rounded-[12px] px-2.5 text-[var(--foreground)] no-underline outline-none focus-visible:ring-[length:var(--ns-focus-width,2px)] focus-visible:ring-[color:var(--ns-focus-color,var(--ring))] max-[480px]:hover:bg-[var(--accent)]">
            {it.icon && (
              <span aria-hidden="true" className="grid size-8 shrink-0 place-items-center rounded-[9px] bg-[var(--muted)] [&_svg]:size-[15px]">
                {it.icon}
              </span>
            )}
            <span className="flex min-w-0 flex-col leading-[1.3]">
              <span className="text-[length:var(--ns-type-label)] font-semibold">{it.title}</span>
              {it.description && <span className="truncate text-[11.5px] text-[color:var(--ns-ink-support,color-mix(in_oklab,var(--muted-foreground)_85%,var(--foreground)))]">{it.description}</span>}
            </span>
          </a>
        ))}
      </div>
      {aside && <div className="max-sm:hidden">{aside}</div>}
    </div>
  )
}

export { IslandNav, IslandNavGrid, type IslandNavGridProps, type IslandNavItem, type IslandNavProps }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

/*
 * The shared parts: the rolling label every state change goes through, the check that draws
 * itself, the spinner and the live dot, and a timeline that schedules a component's steps and clears
 * them when it unmounts. Every class string is a plain literal (the shadcn CLI only rewrites those for
 * apps with tailwind.prefix). Keyframes (ns-*) live in the foundation CSS.
 *
 * Easing vocabulary (the design's names): press var(--ns-ease-press) for scale on press; roll
 * var(--ns-ease-reshape) for label rolls, menus and width morphs; pop var(--ns-ease-pop) for
 * icon swaps and checks landing; draw cubic-bezier(.6,0,.2,1) for strokes and sweeps; exit
 * cubic-bezier(.6,0,.9,.5) for things leaving.
 */

/** Runs on the client before paint, and as an effect on the server (React 18 warns about layout effects there). */
const useIsomorphicLayoutEffect = typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect

/** Points one ref (callback or object) at `node`. */
function assignRef<T>(ref: React.Ref<T> | undefined, node: T | null) {
  if (typeof ref === "function") ref(node)
  else if (ref) (ref as React.MutableRefObject<T | null>).current = node
}

/** Sets every ref passed (callback or object), so a component can keep its own ref and forward the caller's. */
function useComposedRefs<T>(...refs: (React.Ref<T> | undefined)[]) {
  const latest = React.useRef(refs)
  useIsomorphicLayoutEffect(() => {
    latest.current = refs
  })
  return React.useCallback((node: T | null) => {
    for (const ref of latest.current) assignRef(ref, node)
  }, [])
}

/** Schedules a component's steps; every pending step is cleared on clear() and on unmount. */
function useTimeline() {
  const timers = React.useRef<Set<ReturnType<typeof setTimeout>>>(new Set())
  React.useEffect(() => {
    const set = timers.current
    return () => {
      for (const t of set) clearTimeout(t)
      set.clear()
    }
  }, [])
  return React.useMemo(
    () => ({
      after(ms: number, fn: () => void) {
        const t = setTimeout(() => {
          timers.current.delete(t)
          fn()
        }, ms)
        timers.current.add(t)
        return t
      },
      clear() {
        for (const t of timers.current) clearTimeout(t)
        timers.current.clear()
      },
    }),
    []
  )
}

/** Resolves after `ms` (a minimum time a state shows, so a fast promise still reads). */
const wait = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms))

/**
 * A fixed-height window over a stack of rows; row `index` shows, the others roll past (.5s roll). Only
 * the showing row is in the accessibility tree, so the button's name is always the current label.
 */
function RollingLabel({ rows, index, size = "default", align = "center", fit = false, rowHeight, className }: { rows: readonly React.ReactNode[]; index: number; size?: "default" | "sm" | undefined; align?: "center" | "start" | undefined; /** Rows as wide as their own text (inside a window sized to the active row). */ fit?: boolean | undefined; /** A row height in px, for titles (overrides size). */ rowHeight?: number | undefined; className?: string | undefined }) {
  const height = rowHeight ?? (size === "sm" ? 18 : 20)
  return (
    <span data-slot="rolling-label" className={cn("relative block overflow-hidden", !rowHeight && (size === "sm" ? "h-[18px]" : "h-5"), className)} style={rowHeight ? { height: rowHeight } : undefined}>
      <span
        className={cn("flex flex-col transition-transform duration-500 ease-[var(--ns-ease-reshape)] motion-reduce:transition-none", fit && (align === "center" ? "items-center" : "items-start"))}
        style={{ transform: `translateY(${-index * height}px)` }}
      >
        {rows.map((row, i) => (
          <span
            key={i}
            aria-hidden={i === index ? undefined : true}
            className={cn("flex shrink-0 items-center gap-2 whitespace-nowrap", !rowHeight && (size === "sm" ? "h-[18px]" : "h-5"), align === "center" ? "justify-center" : "justify-start", fit && "w-max")}
            style={rowHeight ? { height: rowHeight, lineHeight: `${rowHeight}px` } : undefined}
          >
            {row}
          </span>
        ))}
      </span>
    </span>
  )
}

/** The check that draws itself in (.45s draw after .15s) when `shown`. */
function DrawCheck({ shown, className }: { shown: boolean; className?: string | undefined }) {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" className={cn("size-4 shrink-0", className)} fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
      <path
        d="M20 6 9 17l-5-5"
        className="[stroke-dasharray:24] transition-[stroke-dashoffset] delay-150 duration-[450ms] ease-[cubic-bezier(.6,0,.2,1)] motion-reduce:transition-none"
        style={{ strokeDashoffset: shown ? 0 : 24 }}
      />
    </svg>
  )
}

/** The 14px spinner: an arc turning every .7s. */
function Spinner({ className }: { className?: string | undefined }) {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" className={cn("size-3.5 shrink-0 animate-[ns-spin_.7s_linear_infinite]", className)} fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
      <circle cx="12" cy="12" r="9" className="[stroke-dasharray:20_40]" />
    </svg>
  )
}

/** A 7px dot with a ring that keeps blooming out of it (live). */
function LiveDot({ className }: { className?: string | undefined }) {
  return (
    <span aria-hidden="true" className={cn("relative inline-flex size-[7px] shrink-0", className)}>
      <span className="absolute inset-0 animate-[ns-live_1.2s_ease-out_infinite] rounded-full bg-current" />
      <span className="relative size-full rounded-full bg-current" />
    </span>
  )
}

/**
 * Where overlays (menus, tooltips) portal to. Unset, they portal to document.body, where your
 * :root theme applies. Set it when the theme lives on an element instead of :root:
 *   <PortalContext.Provider value={element}>…</PortalContext.Provider>
 */
const PortalContext = React.createContext<HTMLElement | null>(null)

/** The container for an overlay's Portal: the provided element, else undefined (document.body). */
function usePortal() {
  return React.useContext(PortalContext) ?? undefined
}

/**
 * Writes text to the clipboard and resolves true only when it landed (falls back to a hidden textarea
 * where the async API is missing or blocked). Show "Copied" only on true.
 */
async function copyText(text: string): Promise<boolean> {
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(text)
      return true
    }
  } catch {
    // Blocked (permissions, an insecure origin): try the fallback below.
  }
  try {
    const area = document.createElement("textarea")
    area.value = text
    area.setAttribute("readonly", "")
    area.style.position = "fixed"
    area.style.opacity = "0"
    document.body.appendChild(area)
    area.select()
    const copied = document.execCommand("copy")
    area.remove()
    return copied
  } catch {
    return false
  }
}

/**
 * A callback ref that sets the inert attribute (React 18 has no inert prop): hidden panes and folded
 * sections stay out of the tab order and the accessibility tree.
 */
function inertRef(on: boolean) {
  return (node: HTMLElement | null) => {
    node?.toggleAttribute("inert", on)
  }
}

/** True while an IME is composing: key handlers that commit text ignore those keys. */
function composing(event: React.KeyboardEvent) {
  return event.nativeEvent.isComposing || event.keyCode === 229
}

/** True when focus is in a text field (single-key shortcuts stay out of the way). */
function typingInField() {
  const el = document.activeElement as HTMLElement | null
  return Boolean(el && (el.tagName === "INPUT" || el.tagName === "TEXTAREA" || el.tagName === "SELECT" || el.isContentEditable))
}

/** A label's text for the live region: the label itself when it is text, else `fallback`. */
function spoken(label: React.ReactNode, fallback: string) {
  return typeof label === "string" || typeof label === "number" ? String(label) : fallback
}

/** A polite live region that says `message` whenever it changes (label rolls, outcomes). */
function Announcer({ message }: { message: string }) {
  return (
    <span aria-live="polite" className="sr-only">
      {message}
    </span>
  )
}

const REDUCED = "(prefers-reduced-motion: reduce)"

/**
 * Whether motion should be calm right now: the OS asks for reduced motion, or `el` sits under
 * data-motion="off". For event handlers and effects (it reads the DOM).
 */
function prefersCalm(el?: Element | null) {
  if (typeof window === "undefined") return false
  return Boolean(window.matchMedia?.(REDUCED).matches || el?.closest('[data-motion="off"]'))
}

/**
 * Whether `el` sits in an RTL scope: the nearest `dir`, as Tailwind's `rtl:` styles read it, so a
 * dir="rtl" panel inside an LTR page (or the reverse) maps pointer and arrow keys the way it's drawn.
 */
function isRtl(el?: Element | null) {
  if (typeof window === "undefined") return false
  if (!el) return document.dir === "rtl"
  try {
    return el.matches(":dir(rtl)")
  } catch {
    return el.closest("[dir]")?.getAttribute("dir") === "rtl"
  }
}

/**
 * The one failure contract every action callback follows: it failed if it threw (handled by the caller),
 * or resolved `false`, a failed Response (`!res.ok`) or an object with an `error` (any value).
 */
function isFailedResult(result: unknown): boolean {
  if (result === false) return true
  if (typeof Response !== "undefined" && result instanceof Response) return !result.ok
  return typeof result === "object" && result !== null && "error" in result && (result as { error: unknown }).error != null
}

/** The message a failure carries, if it has one: a thrown Error's, or `{ error: "text" }`'s / `{ error: { message } }`'s. */
function failureMessage(reason: unknown): string {
  if (reason instanceof Error) return reason.message
  if (typeof reason === "object" && reason !== null && "error" in reason) {
    const e = (reason as { error: unknown }).error
    if (typeof e === "string") return e
    if (typeof e === "object" && e !== null && typeof (e as { message?: unknown }).message === "string") return (e as { message: string }).message
  }
  return ""
}

const noSubscribe = () => () => {}
/**
 * Now, on the client only: null on the server and during hydration (so both render the same in every
 * time zone), then the visitor's clock. For anything that shows "today" without a `today` prop.
 */
function useClientNow(): Date | null {
  const mounted = React.useSyncExternalStore(noSubscribe, () => true, () => false)
  const [now] = React.useState(() => (typeof window === "undefined" ? null : new Date()))
  return mounted ? (now ?? new Date()) : null
}

const subscribeReduced = (onChange: () => void) => {
  const mq = window.matchMedia?.(REDUCED)
  mq?.addEventListener("change", onChange)
  return () => mq?.removeEventListener("change", onChange)
}

/**
 * The OS reduced-motion preference for render, following changes. False on the server and during
 * hydration (so both render the same), then the real value.
 */
function useCalm() {
  return React.useSyncExternalStore(subscribeReduced, () => Boolean(window.matchMedia?.(REDUCED).matches), () => false)
}

export {
  failureMessage,
  isFailedResult,
  isRtl,
  useClientNow,
  Announcer,
  composing,
  copyText,
  DrawCheck,
  inertRef,
  PortalContext,
  prefersCalm,
  LiveDot,
  RollingLabel,
  spoken,
  Spinner,
  typingInField,
  useCalm,
  useComposedRefs,
  useIsomorphicLayoutEffect,
  usePortal,
  useTimeline,
  wait,
}

"use client"

import * as React from "react"


/*
 * The sound library: every component's own synthesised voice (Web Audio, no files), the
 * design's tones ported as they are, for buttons, text fields and progress. They play only inside a
 * SoundProvider that's switched on (its choice is saved in this browser), so a page without the
 * provider stays silent. The AudioContext is made on the first sound, which always follows a gesture.
 */

let audio: AudioContext | null = null

function context(): AudioContext | null {
  if (typeof window === "undefined") return null
  try {
    const Ctor = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext | undefined }).webkitAudioContext
    if (!Ctor) return null
    audio ??= new Ctor()
    if (audio.state === "suspended") void audio.resume()
    return audio
  } catch {
    return null
  }
}

/** A tone. f: Hz, d: seconds, v: peak gain, w: delay (s), to: pitch glide target (Hz). */
function tone(f: number, d: number, type: OscillatorType = "sine", v = 0.06, w = 0, to?: number) {
  const a = context()
  if (!a) return
  const t = a.currentTime + w
  const osc = a.createOscillator()
  const gain = a.createGain()
  osc.type = type
  osc.frequency.setValueAtTime(f, t)
  if (to) osc.frequency.exponentialRampToValueAtTime(to, t + d)
  gain.gain.setValueAtTime(0.0001, t)
  gain.gain.exponentialRampToValueAtTime(v, t + 0.006)
  gain.gain.exponentialRampToValueAtTime(0.0001, t + d)
  osc.connect(gain)
  gain.connect(a.destination)
  osc.start(t)
  osc.stop(t + d + 0.03)
}

/** Band-passed white noise; freq → to sweeps the filter. */
function noise(d: number, v: number, freq: number, to?: number, w = 0) {
  const a = context()
  if (!a) return
  const t = a.currentTime + w
  const length = Math.floor(a.sampleRate * d)
  const buffer = a.createBuffer(1, length, a.sampleRate)
  const channel = buffer.getChannelData(0)
  for (let i = 0; i < length; i++) channel[i] = Math.random() * 2 - 1
  const source = a.createBufferSource()
  source.buffer = buffer
  const filter = a.createBiquadFilter()
  filter.type = "bandpass"
  filter.Q.value = 0.9
  filter.frequency.setValueAtTime(freq, t)
  if (to) filter.frequency.exponentialRampToValueAtTime(to, t + d)
  const gain = a.createGain()
  gain.gain.setValueAtTime(0.0001, t)
  gain.gain.exponentialRampToValueAtTime(v, t + d * 0.35)
  gain.gain.exponentialRampToValueAtTime(0.0001, t + d)
  source.connect(filter)
  filter.connect(gain)
  gain.connect(a.destination)
  source.start(t)
  source.stop(t + d + 0.02)
}

